"""Line-oriented message adapter for a future externally hosted model pilot.

No model client, network connection, API credential, shell tool, or OS sandbox.
TASK is evaluator-owned; stdin is the entire proposer's interface. The task and
messages are PUBLIC in the included smoke case, not hidden evaluation material.
"""
from fractions import Fraction as F
from pathlib import Path
import json
import sys
from execution_gate import Gate,Client,ManualClock
from verify_trace import check
from pilot_runner import ARMS,need,check_sources


def emit(value):
    print(json.dumps(value,sort_keys=True),flush=True)


def session(task,arm,lines):
    check_sources()
    need(arm in ARMS,'ARM')
    need(set(task)=={'id','owner','leases','after','max_messages'},'TASK_SCHEMA')
    need(type(task['max_messages']) is int and 1<=task['max_messages']<=128,'MESSAGE_LIMIT')
    need(isinstance(task['leases'],list) and 0<len(task['leases'])<=32,'LEASE_LIMIT')
    clock=ManualClock();gate=Gate(clock,beta='1/10');truth={}
    try:
        worst=max(F(l['bound']) for l in task['leases'])
        for l in task['leases']:
            truth[l['id']]=F(l['bound'])
            w='0' if arm=='S' else '1/100' if arm=='Q' else str(worst if arm=='W' else l['bound'])
            need(gate.install(l['id'],l['owner'],w,l['until'],l['duration'],l['closed'])['status']=='INSTALLED','INSTALL')
        emit({'kind':'ready','task':task['id'],'owner':task['owner'],
              'interface':'prepare(lease,action), commit(ticket), abort(ticket)',
              'max_messages':task['max_messages']})
        used=0
        for raw in lines:
            if used>=task['max_messages']:break
            used+=1
            if len(raw.encode())>8192:
                reply={'status':'REFUSED','reason':'MESSAGE_BYTES_LIMIT'}
            else:
                try:
                    message=json.loads(raw)
                except json.JSONDecodeError:
                    reply={'status':'REFUSED','reason':'INVALID_JSON'}
                else:
                    reply=({'status':'REFUSED','reason':'DENY_ALL'} if arm=='D'
                           else Client(gate,task['owner']).send(message))
            emit({'kind':'response','step':used,'response':reply})
            for change in task['after'].get(str(used),[]):
                if set(change)=={'kind','amount'} and change['kind']=='advance':
                    clock.advance(change['amount'])
                elif change.get('kind')=='control' and change.get('op') in ('STOP','REVOKE','MODEL_CHANGE'):
                    gate.control(change['op'],change.get('lease'))
                else:
                    raise ValueError('AUTHORITY_SCHEDULE')
                emit({'kind':'authority_event','after_step':used,'event':change})
        log=gate.export();q=F(1)
        for e in log['events']:
            if e['kind']=='PREPARE':q*=1-truth[e['body']['lease']]
        emit({'kind':'final','messages':used,'trace':log,'trace_check':check(log),
              'declared_reservation_exposure':str(1-q),
              'limits':'These observations contain no independently attested model or physical timing provenance.'})
    finally:
        gate.close()


if __name__=='__main__':
    need(len(sys.argv)==3,'Usage: python agent_session.py TASK.json D|S|Q|W|R < messages.jsonl')
    path=Path(sys.argv[1]);need(path.stat().st_size<=200000,'TASK_BYTES_LIMIT')
    session(json.loads(path.read_text()),sys.argv[2],sys.stdin)
```

